export const APP_STAMP_SRC = '/public-assets/app-stamp.js'
// Nonce is generated by the existing browser renderer; no new CSP allowance.
export const releaseStampTag = nonce => `<script nonce="${String(nonce).replace(/[&"<>]/g, c => ({ '&': '&amp;', '"': '&quot;', '<': '&lt;', '>': '&gt;' }[c]))}" src="${APP_STAMP_SRC}" defer></script>`
